fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Given assumptions:
    // - list.len() > 0
    // - 0 < n < list.len()
    //
    // We build a new vector by first pushing elements from index n to the end,
    // then pushing elements from index 0 to n (exclusive), preserving order.

    let len = list.len();
    let mut new_list = Vec::with_capacity(len);

    // Push elements from n to end
    new_list.extend_from_slice(&list[n..]);

    // Push elements from start to n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}